// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  item.json.myNewField = 1;
}

return $input.all();

const existingPages = $('Webhook').first().json.body.pages.map(i => i.toString());

const pages = $input.first().json.rows.filter(page => !existingPages.includes(page.page_id));

return pages;

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  item.json.cookies = $('Login').first().json.cookies;
}

return $input.all();

const workspace_id = $('Webhook').first().json.body.workspace_id;
const api_key = $('Webhook').first().json.body.api_key;
const webhook_url = $('Webhook').first().json.body.webhook_url;
const pages = $input.all().map(i => i.json)

return [
  {
    json: {
      workspace_id,
      api_key,
      webhook_url,
      pages
    }
  }
]

parameters.scriptCode:
const { cookies } = $json;

// ---------- Setup ----------
if (cookies && cookies.length) {
    await $page.setCookie(...cookies);
}
await $page.setViewport({ width: 1512, height: 982, deviceScaleFactor: 1 });
await $page.goto('https://meta-digitrading.lhike-erp.com/pages?arch=0', {
    waitUntil: 'networkidle2',
    timeout: 60000
});

async function waitForLoadingToClear() {
    await $page.waitForFunction(() => {
        const el = document.querySelector('#global-preloader');
        if (!el) return true;
        return window.getComputedStyle(el).display === 'none';
    }, { timeout: 60000 });
    await new Promise(resolve => setTimeout(resolve, 1500));
}
await waitForLoadingToClear();

// ---------- Wait for the DataTable to finish its AJAX/redraw ----------
async function waitForTableSettled() {
    // #tblpage_processing is DataTables' own spinner
    await $page.waitForFunction(() => {
        const p = document.querySelector('#tblpage_processing');
        if (p && window.getComputedStyle(p).display !== 'none') return false;
        // require at least one real data row present
        return document.querySelectorAll('#tblpage tbody tr[role="row"]').length > 0;
    }, { timeout: 60000 });
    await new Promise(resolve => setTimeout(resolve, 300));
}

await $page.waitForSelector('#tblpage tbody tr', { timeout: 30000 });
await waitForTableSettled();

function formatDate(date) {
  const mm = String(date.getMonth() + 1).padStart(2, '0');
  const dd = String(date.getDate()).padStart(2, '0');
  const yyyy = date.getFullYear();
  return `${mm}/${dd}/${yyyy}`;
}

const endDate = new Date();
const startDate = new Date();
startDate.setMonth(startDate.getMonth() - 6);


await $page.type('input#ssdate', formatDate(startDate), {
    delay: 50
});
await $page.type('input#sedate', formatDate(endDate), {
    delay: 50
});

await $page.click('a#btndtsearch');

await $page.waitForNetworkIdle({
    idleTime: 500,
    timeout: 30000
});

await waitForLoadingToClear();

await waitForTableSettled();

// ---------- Bump page length to 100 to minimize page hops ----------
await $page.evaluate(() => {
    const sel = document.querySelector('select[name="tblpage_length"]');
    if (sel) {
        sel.value = '100';
        sel.dispatchEvent(new Event('change', { bubbles: true }));
        if (window.jQuery) window.jQuery(sel).trigger('change');
    }
});
await waitForTableSettled();

// ---------- Extract the currently visible page ----------
// Columns: No | Date Created | Name | Owner | Intern & Brands | Status | Platform | (Actions - skipped)
async function extractCurrentPage() {
    return await $page.evaluate(() => {
        const rows = Array.from(
            document.querySelectorAll('#tblpage tbody tr[role="row"]')
        );

        return rows.map(row => {
            const cells = Array.from(row.querySelectorAll('td'));
            if (cells.length < 7) return null;

            const txt = (el) => el ? el.textContent.trim().replace(/\s+/g, ' ') : '';

            const nameCell = cells[2];
            const nameLink = nameCell.querySelector('a');
            const profileUrl = nameLink ? nameLink.href : null;

            let pageId = null;
            const dataIdEl = row.querySelector('[data-id]');
            if (dataIdEl) {
                pageId = dataIdEl.getAttribute('data-id');
            } else {
                const viewLink = row.querySelector('a[href*="pages/view/"], a[href*="pages/edit/"]');
                if (viewLink) {
                    const m = viewLink.getAttribute('href').match(/pages\/(?:view|edit)\/(\d+)/);
                    if (m) pageId = m[1];
                }
            }

            // --- Hidden ID #2: Facebook page id from the profile URL ---
            let fbPageId = null;
            if (profileUrl) {
                // handles profile.php?id=..., and also /<vanity>-<digits> style urls
                const m = profileUrl.match(/[?&]id=(\d+)/);
                if (m) fbPageId = m[1];
            }

            return {
                no: txt(cells[0]),
                page_id: pageId,          // internal ERP id (hidden)
                fb_page_id: fbPageId,     // Facebook numeric id (hidden in URL)
                date_created: txt(cells[1]),
                name: txt(nameCell),
                profile_url: profileUrl,
                owner: txt(cells[3]),
                intern_brands: txt(cells[4]),
                status: txt(cells[5]),
                platform: txt(cells[6])
                // cells[7] = Actions -> skipped
            };
        }).filter(Boolean);
    });
}

// ---------- Walk every page, dedupe by "No" ----------
const byNo = new Map();
let guard = 0; // hard stop against infinite loops

while (guard++ < 100) {
    const pageRows = await extractCurrentPage();
    pageRows.forEach(r => {
        const key = r.page_id || r.no; // page_id preferred, No as fallback
        if (key) byNo.set(key, r);
    });

    // Is the Next button disabled? -> we're on the last page
    const isLast = await $page.evaluate(() => {
        const next = document.querySelector('#tblpage_paginate .next');
        return !next || next.classList.contains('disabled');
    });
    if (isLast) break;

    // Remember the first row's identity so we can detect the redraw
    const beforeFirst = pageRows.length ? (pageRows[0].page_id || pageRows[0].no) : null;

    await $page.evaluate(() => {
        const a = document.querySelector('#tblpage_paginate .next a');
        if (a) a.click();
    });
    await waitForTableSettled();

    // Confirm the page actually changed before looping again
    await $page.waitForFunction((prevKey) => {
        const row = document.querySelector('#tblpage tbody tr[role="row"]');
        if (!row) return false;
        const btn = row.querySelector('[data-id]');
        const firstNo = row.querySelector('td') ? row.querySelector('td').textContent.trim() : '';
        const nowKey = btn ? btn.getAttribute('data-id') : firstNo;
        return nowKey && nowKey !== prevKey;
    }, { timeout: 30000 }, beforeFirst).catch(() => {}); // don't hard-fail; guard + isLast still protect us
}

const allRows = Array.from(byNo.values());

// ---------- Grab the reported total for a sanity check ----------
const reportedTotal = await $page.evaluate(() => {
    const info = document.querySelector('#tblpage_info');
    if (!info) return null;
    const m = info.textContent.match(/of\s+([\d,]+)\s+entries/i);
    return m ? parseInt(m[1].replace(/,/g, ''), 10) : null;
});

// ---------- Return ----------
return [
    {
        json: {
            totalRows: allRows.length,
            reportedTotal,          // should match totalRows (e.g. 252)
            complete: reportedTotal == null ? null : allRows.length === reportedTotal,
            rows: allRows,
            status: "success"
        }
    }
];

const { cookies, page_id, ...info } = $json;

if (cookies?.length) {
    await $page.setCookie(...cookies);
}

await $page.setViewport({
    width: 1512,
    height: 982,
    deviceScaleFactor: 1
});

await $page.goto(
    `https://meta-digitrading.lhike-erp.com/pages/view/${page_id}`,
    {
        waitUntil: 'networkidle2',
        timeout: 60000
    }
);

const data = await $page.evaluate(() => {
    return {
        shop_id:
            document.querySelector('#txtshopid')?.value || null,

        pos_token:
            document.querySelector('#txtapikey')?.value || null,
    };
});

return [
    {
        json: {
            page_id,
            ...data,
            ...info
        }
    }
];
